rounding.find:
with localcontext() as ctx:
    ctx.rounding = ROUND_HALF_UP
    return amount.quantize(CENT)

rounding.replace:
with localcontext() as ctx:
    ctx.rounding = ROUND_HALF_UP
return amount.quantize(CENT)

tax-per-line.find:
nets = defaultdict(Decimal)
for line in lines:
    nets[line.tax_rate] += line.net
return {rate: round_cents(net * rate) for rate, net in sorted(nets.items())}

tax-per-line.replace:
taxes = defaultdict(Decimal)
for line in lines:
    taxes[line.tax_rate] += round_cents(line.net * line.tax_rate)
return dict(sorted(taxes.items()))
